def graph_patterns(selection: Selection) -> set[str]:
    patterns = {"P4"} if selection.object_batch else set()
    for step in selection.steps:
        deps = {
            b.step
            for b in step.inputs.values()
            if b.source == "step" or b.source == "object_rows"
        }
        if step.cases:
            patterns.add("P5")
        if step.reviews:
            patterns.add("P3")
        elif len(deps) > 1:
            patterns.add("P2")
        elif deps and not selection.object_batch:
            patterns.add("P1")
    return patterns


def routing_alternatives(selection: Selection, methods: dict) -> list[str]:
    if selection.status != "ready" or any(s.cases for s in selection.steps):
        return []

    def input_contract(method):
        return {
            name: {k: slot[k] for k in ("schema", "meaning", "required", "on_missing")}
            for name, slot in method["inputs"].items()
        }

    selected = {step.method for step in selection.steps}
    contracts = [input_contract(methods[a]) for a in selected if a in methods]
    return list(
        dict.fromkeys(
            method["declaration"]["title"]
            for alias, method in methods.items()
            if alias not in selected and input_contract(method) in contracts
        )
    )[:3]


def review_issue(selection: Selection, enabled: dict[str, bool]) -> str | None:
    if selection.status != "ready":
        return None
    patterns = graph_patterns(selection)
    if selection.routing_required != ("P5" in patterns):
        return "selection_route"
    if "P4" in patterns and (len(selection.steps) != 2 or patterns != {"P4"}):
        return "selection_capability"
    if "P3" in patterns and (len(selection.steps) not in (2, 3) or patterns != {"P3"}):
        return "selection_capability"
    for step in selection.steps:
        if step.cases or step.route_input:
            binding = step.inputs.get(step.route_input) if step.route_input else None
            if len(step.cases) < 2 or binding is None or binding.source != "caller":
                return "selection_route"
        if step.reviews:
            deps = {b.step for b in step.inputs.values() if b.source == "step"}
            if set(step.reviews) != deps or len(deps) not in (1, 2):
                return "selection_review"
    # A label alone cannot provide isolation, iteration, or conditional routing.
    if ({"P3", "P4", "P5"} & set(selection.patterns)) - patterns:
        return "selection_patterns"
    if any(not enabled.get(FEATURES[p]) for p in patterns):
        return "selection_capability"
    return None


def normalize_unresolved(value):
    if isinstance(value, dict) and value.get("status") in ("gap", "clarify"):
        return {**value, "steps": [], "patterns": [], "object_batch": None}
    return value


def check_proposal(selection, methods, instructions, enabled):
    """Check the model's draft against the catalog sealed into this round."""
    if issue := review_issue(selection, enabled):
        advice = {
            "selection_route": "check routing_required, caller input and case labels",
            "selection_capability": "check runtime patterns and review or batch limits",
            "selection_review": "bind reviewed outputs and list their steps in reviews",
            "selection_patterns": "use P3/P4/P5 only when the steps implement them",
        }
        raise ValueError(f"{issue}: {advice[issue]}")
    seen = {}
    for step in selection.steps:
        candidates = set(step.cases.values()) or {step.method}
        if step.method not in candidates or len(candidates) < len(step.cases):
            raise ValueError(
                f"{step.id}: use distinct route candidates including the named method"
            )
        if candidates & instructions.keys():
            if not (
                len(selection.steps) == 1
                and step.method in instructions
                and not (
                    step.inputs
                    or step.reviews
                    or step.route_input
                    or step.cases
                    or selection.patterns
                    or selection.object_batch
                )
            ):
                raise ValueError(
                    f"{step.id}: an instruction source can only be used alone"
                )
        elif missing := candidates - methods.keys():
            raise ValueError(
                f"{step.id}: method outside the authorized catalog: {sorted(missing)}"
            )
        dependencies = {
            binding.step
            for binding in step.inputs.values()
            if binding.source in ("step", "object_rows")
        }
        if step.id in seen or not dependencies <= seen.keys():
            raise ValueError(
                f"{step.id}: use distinct step IDs and bind only earlier results"
            )
        if step.reviews and not all(
            methods[alias].get("isolated_instruction")
            for alias in [step.method, *(seen[dep] for dep in step.reviews)]
        ):
            raise ValueError(
                f"{step.id}: independent review needs isolated instruction methods"
            )
        seen[step.id] = step.method


def expand(
    selection: Selection,
    tools: dict[str, FrozenMethod],
    template: DeliveryCriteria | None,
    enabled: dict[str, bool],
    *,
    required_cases: dict[str, set[str]],
    title: str | None = None,
):
    if selection.status != "ready":
        raise ValueError("selection_unresolved")
    graph_steps = []
    roles: dict[str, Any] = {}
    permissions, approvals = {}, []
    issue = review_issue(selection, enabled)
    if issue:
        raise ValueError(issue)
    dependencies: dict[str, set[str]] = {}
    route_values: dict[str, set[str]] = {}
    for step in selection.steps:
        aliases = list(step.cases.values()) if step.cases else [step.method]
        if (
            step.method not in aliases
            or any(a not in tools for a in aliases)
            or len(aliases) != len(set(aliases))
        ):
            raise ValueError("selection_candidate")
        chosen = tools[step.method].definition
        interface = chosen.interfaces()
        inputs = {}
        deps = set()
        for name, item in interface["inputs"].items():
            binding = step.inputs.get(name)
            if binding is None:
                if item["required_by"]:
                    raise ValueError("selection_input")
                continue
            if binding.source in {"literal", "resource"}:
                raise ValueError("selection_input")
            if binding.source == "step" or binding.source == "object_rows":
                deps.add(binding.step)
            inputs[name] = dict(
                slot=item["slot"], binding=binding.model_dump(mode="json")
            )
        if step.inputs.keys() - inputs.keys() or step.id in dependencies:
            raise ValueError("selection_input")
        dependencies[step.id] = deps
        graph_step = dict(
            id=step.id,
            candidates=[tools[a].reference.model_dump(mode="json") for a in aliases],
            inputs=inputs,
            depends_on=sorted(deps),
            outputs={n: v["slot"] for n, v in interface["outputs"].items()},
            always_required=True,
            required_when="always",
            select_when="always",
            on_failure="fail",
        )
        if step.cases or step.route_input:
            if not step.route_input or len(step.cases) < 2:
                raise ValueError("selection_route")
            route_values[step.id] = set(step.cases)
            graph_step["candidate_choice"] = dict(
                input=step.route_input,
                cases=[
                    dict(
                        equals=label,
                        candidate=tools[a].reference.model_dump(mode="json"),
                    )
                    for label, a in step.cases.items()
                ],
            )
        if step.reviews:
            for alias in (
                selection_step.method
                for selection_step in selection.steps
                if selection_step.id in {*step.reviews, step.id}
            ):
                worker = tools.get(alias)
                if (
                    not worker
                    or worker.definition.procedure.kind != "direct"
                    or worker.definition.procedure.implementation.kind
                    not in ("registered_instruction", "skill_instruction")
                ):
                    raise ValueError("selection_capability")
            if (
                len(deps) not in (1, 2)
                or set(step.reviews) != deps
                or any(dep == step.id for dep in deps)
            ):
                raise ValueError("selection_review")
            for dep in deps:
                roles.setdefault(dep, dict(isolation_group=dep))
            roles[step.id] = dict(
                isolation_group=step.id,
                handoff_from=sorted(deps),
                review_requirements={dep: "isolated_reviewer" for dep in deps},
            )
        for alias in aliases:
            child = tools[alias].definition
            for req in child.access_requirements:
                if (
                    req.requirement_id in permissions
                    and req != permissions[req.requirement_id]
                ):
                    raise ValueError("selection_permission_conflict")
                permissions[req.requirement_id] = req
            for rule in child.what_requires_approval:
                if rule not in approvals:
                    approvals.append(rule)
        graph_steps.append(graph_step)
    if (
        selection.routing_required != bool(route_values)
        or required_cases != route_values
    ):
        raise ValueError("selection_route")
    tail = selection.steps[-1]
    needed = {tail.id}
    for s in reversed(selection.steps):
        if s.id not in needed:
            raise ValueError("selection_disconnected")
        needed.update(dependencies[s.id])
    final = tools[tail.method].definition
    doc = final.document()
    exports = {
        n: dict(step=tail.id, output=n, always_present=i["always_present"])
        for n, i in final.interfaces()["outputs"].items()
    }
    doc.update(
        access_requirements=list(permissions.values()), what_requires_approval=approvals
    )
    procedure: dict[str, Any] = dict(
        kind="orchestration",
        instructions="\n".join(step.task for step in selection.steps),
        steps=graph_steps,
        exports=exports,
        max_depth=16,
        max_steps=100,
        max_expansions=1000,
        max_replans=0,
    )
    if selection.object_batch:
        procedure["object_batch"] = selection.object_batch.model_dump()
    doc["procedure"] = procedure
    if template:
        declaration = doc["capability_declaration"]
        declaration.update(
            title=title or declaration["title"],
            purpose=template.goal,
            promises={
                **declaration["promises"],
                "template_delivery": template.deliverable,
            },
        )
        if declaration.get("conditions"):
            declaration["conditions"].pop("template_delivery", None)
        doc["how_to_validate"] = [
            *(
                v
                for v in doc["how_to_validate"]
                if v["promise_id"] != "template_delivery"
            ),
            dict(
                promise_id="template_delivery",
                outputs=list(exports),
                check=template.check,
                evidence=template.evidence,
                on_failure="fail",
            ),
        ]
    definition = FormalMethodDefinition.model_validate(doc)
    if roles and isinstance(definition.procedure, Orchestration):
        definition.procedure.validate_collaboration(roles_typed(roles))
        if not review_group(
            definition.procedure.model_copy(
                update={"collaboration": roles_typed(roles)}
            )
        ):
            raise ValueError("selection_capability")
    return FormalMethodDraft(
        definition=definition, source=None, allowed_callers=("host",)
    ), roles or None


def roles_typed(roles):
    from app.domain.workbench.formal_method_generated import CollaborationStep

    return {k: CollaborationStep.model_validate(v) for k, v in roles.items()}


def available(definition, runtime):
    procedure = definition.procedure
    if procedure.kind == "direct":
        kind = procedure.implementation.kind
        if kind not in (
            "mcp",
            "a2a",
            "registered_script",
            "skill_script",
            "skill_instruction",
            "registered_instruction",
            "service_function",
        ):
            return False
        if kind in ("registered_script", "skill_script"):
            return runtime.get("script") is True
        if kind == "service_function":
            return runtime.get("material_read") is True
    else:
        flags = runtime["patterns"]
        if (
            procedure.collaboration
            and not flags.get("independent_review")
            or procedure.object_batch
            and not flags.get("object_batch")
            or procedure.has_candidate_choice
            and not flags.get("conditional")
        ):
            return False
    return True


def conditional_witnesses(graph, leaf_counts):
    """Cover every candidate and the heaviest route without a Cartesian product.

    Choices change only the invoked subtree. compile_method already bounds depth,
    steps and expansions over all candidates. Leaf counts add across independent
    caller inputs, while all steps reading the same input share one label.
    """
    weights: dict[str, dict[str, int]] = {}
    for step in graph.steps:
        choice = step.candidate_choice
        if choice is None:
            continue
        name = step.inputs[choice.input].binding.name
        labels = {case.equals for case in choice.cases}
        totals = weights.setdefault(name, dict.fromkeys(sorted(labels), 0))
        if labels != totals.keys():
            # Each declared case must reach all mandatory steps.
            raise ValueError("selection_route")
        for case in choice.cases:
            totals[case.equals] += leaf_counts.get(case.candidate, 1)
    worst = {
        name: max(totals, key=totals.__getitem__) for name, totals in weights.items()
    }
    yield worst
    for name, totals in weights.items():
        for label in totals:
            if label != worst[name]:
                yield {**worst, name: label}


def verify_selection_graph(target, definition, resolved, capabilities, roles=None):
    if any(
        not available(child.definition, capabilities) for child in resolved.values()
    ):
        raise ValueError("selection_capability")
    graph = definition.procedure
    compile_method(target, definition, resolved)
    if graph.kind == "orchestration":
        # A nested method must already have a fixed invocation graph.
        leaf_counts = {}
        for child in resolved.values():
            nested = child.definition.procedure
            if nested.kind == "orchestration":
                if (
                    nested.collaboration
                    or nested.object_batch
                    or nested.has_candidate_choice
                ):
                    raise ValueError("selection_capability")
                nested_plan = expand_unique_plan(
                    child.reference.method_id, child.definition, resolved
                )
                leaf_counts[child.reference] = len(nested_plan.leaf_nodes)
        if graph.has_candidate_choice:
            if graph.collaboration or roles or graph.object_batch:
                raise ValueError("selection_capability")
            for values in conditional_witnesses(graph, leaf_counts):
                expand_unique_plan(target, select_plan(definition, values), resolved)
        else:
            values = {}
            if graph.object_batch:
                keys = [str(i) for i in range(graph.object_batch.max_objects)]
                values = {
                    port.binding.name: keys
                    for step in graph.steps
                    for port in step.inputs.values()
                    if port.binding.source == "object_item"
                }
            if roles:
                definition = definition.model_copy(
                    update={
                        "procedure": graph.model_copy(
                            update={"collaboration": roles_typed(roles)}
                        )
                    }
                )
            expand_unique_plan(target, select_plan(definition, values), resolved)
